const PRECACHE_CONCURRENCY = 4;
// Reserve the same three noncritical cache positions after the new boot entries.
const RUNTIME_CACHE_MAX_ENTRIES = 128 + REQUIRED_RENDER_BOOT_ADDITIONS.length;
// One runtime-only reservation for the exact authored Station map, after a successful fetch.
const RETAINED_STATION_MAP = "/assets/generated/field-aurelia-corridor-objects-v318.webp";
let runtimeCacheMutation = Promise.resolve();

function installCacheKey(asset) {
  if (asset === "/" || asset === "/index.html") return asset;
  const versioned = new URL(asset, self.location.origin);
  versioned.searchParams.set("v", RUNTIME_RELEASE);
  return `${versioned.pathname}${versioned.search}`;
}

async function cacheBootCriticalAssets(cache) {
  const assets = [...BOOT_CRITICAL_ASSETS].map(installCacheKey);
  const unavailable = [];
  let cursor = 0;
  const worker = async () => {
    while (cursor < assets.length) {
      const asset = assets[cursor++];
      try {
        const response = await fetch(asset, { cache: "reload" });
        if (response.status === 200) {
          await cache.put(asset, response);
          continue;
        }
      } catch {
        // A retry of this exact release can reuse its own completed entry.
      }
      try {
        const cached = await cache.match(asset);
        if (cached?.status === 200) continue;
      } catch {}
      unavailable.push(asset);
    }
  };
  await Promise.all(Array.from({ length: Math.min(PRECACHE_CONCURRENCY, assets.length) }, worker));
  if (unavailable.length) {
    throw new Error(`DVA offline boot cache incomplete: ${unavailable.length} required asset(s)`);
  }
}

function runtimeCacheKey(request) {
  const url = new URL(typeof request === "string" ? request : request.url, self.location.origin);
  if (url.origin !== self.location.origin) return null;
  if (url.pathname === "/" || url.pathname === "/index.html") return url.pathname;
  return installCacheKey(url.pathname);
}

function isBootCriticalCacheRequest(request) {
  try {
    return BOOT_CRITICAL_ASSETS.has(new URL(request.url, self.location.origin).pathname);
  } catch {
    return false;
  }
}

async function trimRuntimeCache(cache) {
  const keys = await cache.keys();
  const stationKey = new URL(installCacheKey(RETAINED_STATION_MAP), self.location.origin).href;
  const retained = keys.find((request) => request.url === stationKey);
  let overflow = keys.length - RUNTIME_CACHE_MAX_ENTRIES - (retained ? 1 : 0);
  if (overflow <= 0) return;
  for (const request of keys) {
    if (overflow <= 0) break;
    if (request === retained || isBootCriticalCacheRequest(request)) continue;
    if (await cache.delete(request)) overflow -= 1;
  }
}

function commitRuntimeResponse(request, response) {
  const key = runtimeCacheKey(request);
  if (!key || response.status !== 200) return Promise.resolve();
  const operation = runtimeCacheMutation.catch(() => {}).then(async () => {
    const cache = await caches.open(CACHE_NAME);
    await cache.put(key, response);
    await trimRuntimeCache(cache);
  });
  runtimeCacheMutation = operation;
  return operation;
}

async function matchRuntimeResponse(request) {
  const key = runtimeCacheKey(request);
  if (!key) return null;
  try {
    const cache = await caches.open(CACHE_NAME);
    return (await cache.match(key)) || null;
  } catch {
    return null;
  }
}

async function matchNavigationShell() {
  try {
    const cache = await caches.open(CACHE_NAME);
    return (await cache.match("/index.html")) || (await cache.match("/")) || null;
  } catch {
    return null;
  }
}

self.addEventListener("install", (event) => {
  event.waitUntil(
    caches.open(CACHE_NAME).then(cacheBootCriticalAssets).then(() => self.skipWaiting())
  );
});

self.addEventListener("activate", (event) => {
  event.waitUntil(
    caches.keys().then((keys) => {
      return Promise.all(keys.filter((key) => key !== CACHE_NAME).map((key) => caches.delete(key)));
    })
  );
  self.clients.claim();
});

function mayUseGameShellFallback(request, url) {
  return request.mode === "navigate" &&
    (url.pathname === "/" || url.pathname === "/index.html");
}

self.addEventListener("fetch", (event) => {
  const url = new URL(event.request.url);
  if (url.origin !== self.location.origin) return;
  if (url.pathname.startsWith("/api/")) return;
  if (event.request.method !== "GET") return;
  // Range responses are partial representations: bypass the full-resource cache key.
  if (event.request.headers.has("range")) { event.respondWith(fetch(event.request)); return; }

  const networkResponse = fetch(event.request);
  event.waitUntil(networkResponse.then((response) => {
    return response.ok ? commitRuntimeResponse(event.request, response.clone()) : undefined;
  }).catch(() => {}));
  event.respondWith(networkResponse.then(async (response) => {
    if (response.ok) return response;
    const exact = await matchRuntimeResponse(event.request);
    if (exact) return exact;
    if (mayUseGameShellFallback(event.request, url)) return (await matchNavigationShell()) || response;
    return response;
  }).catch(async () => {
    const exact = await matchRuntimeResponse(event.request);
    if (exact) return exact;
    if (mayUseGameShellFallback(event.request, url)) return (await matchNavigationShell()) || Response.error();
    return Response.error();
  }));
});
